KIND_PERMS = {"ram": "rw", "l2lock": "rw", "device": "rwv", "flash": "rv", "alias": "rw", "pcie": "rwv", "rom": "rv"}


def dense(regs):
    if len(regs) < 4:
        return False
    span = max(o + 4 * max(c, 1) for o, _, _, c, _ in regs)
    used = sum(4 * max(c, 1) for _, _, _, c, _ in regs)
    return used * 2 >= span and all(w == 32 for _, _, w, _, _ in regs)


def run():
    from ghidra.program.model.data import StructureDataType, UnsignedIntegerDataType, CategoryPath
    from ghidra.program.model.symbol import SourceType
    mem = currentProgram.getMemory()  # noqa: F821
    st = currentProgram.getSymbolTable()  # noqa: F821
    af = currentProgram.getAddressFactory().getDefaultAddressSpace()  # noqa: F821
    dtm = currentProgram.getDataTypeManager()  # noqa: F821
    A = lambda v: af.getAddress(v)

    def free(base, size):
        return not any(b.getStart().getOffset() < base + size and b.getEnd().getOffset() >= base for b in mem.getBlocks())

    n_blk = n_lbl = n_str = 0
    for name, base, size, kind, desc in REGIONS:
        if kind in ("hazard",) or not free(base, size):
            continue
        b = mem.createUninitializedBlock(name, A(base), size, False)
        p = KIND_PERMS.get(kind, "rw")
        b.setRead(True)
        b.setWrite("w" in p)
        b.setExecute(kind in ("flash", "rom"))
        b.setVolatile("v" in p)
        b.setComment(desc)
        n_blk += 1
    for name, base, size, regs, desc in BLOCKS:
        if free(base, size):
            b = mem.createUninitializedBlock(name, A(base), size, False)
            b.setRead(True)
            b.setWrite(True)
            b.setExecute(False)
            b.setVolatile(True)
            b.setComment(desc)
            n_blk += 1
        for off, rn, w, cnt, stride in regs:
            for i in range(max(cnt, 1) if cnt <= 32 else 1):
                nm = "%s_%s" % (name.upper(), rn) + ("_%d" % i if cnt > 1 else "")
                try:
                    st.createLabel(A(base + off + i * stride), nm, SourceType.USER_DEFINED)
                    n_lbl += 1
                except Exception as e:  # noqa: BLE001
                    print("label %s: %s" % (nm, e))
        if dense(regs):
            s = StructureDataType(CategoryPath("/hwdb"), name + "_regs", 0)
            pos = 0
            for off, rn, w, cnt, stride in sorted(regs):
                if off < pos or cnt > 32:
                    continue
                if off > pos:
                    s.growStructure(off - pos)
                    pos = off
                for i in range(max(cnt, 1)):
                    s.add(UnsignedIntegerDataType.dataType, 4, rn + ("_%d" % i if cnt > 1 else ""), None)
                    pos += 4
            dt = dtm.addDataType(s, None)
            try:
                currentProgram.getListing().createData(A(base), dt)  # noqa: F821
                n_str += 1
            except Exception as e:  # noqa: BLE001
                print("struct %s: %s" % (name, e))
    args = list(getScriptArgs())  # noqa: F821
    prog = currentProgram.getName().lower()  # noqa: F821
    n_fn = 0
    for bn, (base, fl) in FUNCS.items():
        if (args and args[0] != bn) or (not args and bn not in prog):
            continue
        fm = currentProgram.getFunctionManager()  # noqa: F821
        for name, addr, role in fl:
            a = A(addr)
            f = fm.getFunctionAt(a)
            if f is None:
                f = createFunction(a, name)  # noqa: F821
            elif f.getName() != name:
                f.setName(name, SourceType.USER_DEFINED)
            if f is not None and role:
                f.setComment(role)
            n_fn += 1
    print("hwdb import: %d blocks, %d labels, %d structs, %d functions" % (n_blk, n_lbl, n_str, n_fn))


try:
    currentProgram  # noqa: F821
except NameError:
    pass
else:
    run()
